(function(){if(window.__siteLayoutToggleInitialized){return;}
window.__siteLayoutToggleInitialized=true;var STORAGE_KEY='kl-site-layout';var LAYOUTS=['embedded','floating','flat'];var DEFAULT_LAYOUT='embedded';function normalizeLayout(layout){return LAYOUTS.indexOf(layout)!==-1?layout:DEFAULT_LAYOUT;}
function readLayout(){try{return normalizeLayout(localStorage.getItem(STORAGE_KEY));}catch(error){return DEFAULT_LAYOUT;}}
function writeLayout(layout){try{localStorage.setItem(STORAGE_KEY,normalizeLayout(layout));}catch(error){console.warn('[layout-toggle] 无法写入本地布局状态',error);}}
function closeDropdown(){document.querySelectorAll('.site-layout-toggle--open').forEach(function(wrapper){wrapper.classList.remove('site-layout-toggle--open');});document.querySelectorAll('[data-layout-toggle]').forEach(function(button){button.setAttribute('aria-expanded','false');});}
function syncOptions(layout){document.querySelectorAll('[data-layout-option]').forEach(function(option){var selected=option.getAttribute('data-layout-option')===layout;option.setAttribute('aria-pressed',selected?'true':'false');});}
function applyLayout(layout){var normalized=normalizeLayout(layout);document.documentElement.setAttribute('data-site-layout',normalized);writeLayout(normalized);syncOptions(normalized);}
document.addEventListener('click',function(event){var toggleButton=event.target.closest('[data-layout-toggle]');if(toggleButton){var wrapper=toggleButton.closest('.site-layout-toggle');if(wrapper){var willOpen=!wrapper.classList.contains('site-layout-toggle--open');closeDropdown();wrapper.classList.toggle('site-layout-toggle--open',willOpen);toggleButton.setAttribute('aria-expanded',willOpen?'true':'false');}
return;}
var option=event.target.closest('[data-layout-option]');if(option){applyLayout(option.getAttribute('data-layout-option'));closeDropdown();return;}
if(!event.target.closest('.site-layout-dropdown')){closeDropdown();}});document.addEventListener('keydown',function(event){if(event.key==='Escape'){closeDropdown();}});function initialize(){syncOptions(readLayout());}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initialize);}else{initialize();}})();